import{_ as t,I as r,g as a,j as l}from"./chunks/framework.Ha9mtr6N.js";const u=JSON.parse('{"title":"Калькулятор (Рецепты)","description":"Создание технологических карт, расчет себестоимости и накладных расходов в ОмниКрафт ЕРП.","frontmatter":{"title":"Калькулятор (Рецепты)","description":"Создание технологических карт, расчет себестоимости и накладных расходов в ОмниКрафт ЕРП.","order":6},"headers":[],"relativePath":"ru/docs/spaces/production/calculator.md","filePath":"ru/docs/spaces/production/calculator.md"}'),s={name:"ru/docs/spaces/production/calculator.md"};function e(n,o,i,c,d,g){return r(),a("div",null,[...o[0]||(o[0]=[l('<div class="warning custom-block"><p class="custom-block-title">📌 Документация находится в разработке</p><p><strong>Уважаемые пользователи!</strong></p><p>Поскольку ОмниКрафт ЕРП сейчас находится в стадии активной бета-версии, регулярно дорабатывается и расширяется, справочные материалы также обновляются постепенно.</p><p>На данный момент воспринимайте документацию как ориентировочную — она является неполной, может временно не содержать описание некоторых функций или содержать неточности.</p></div><h1 id="🧮-калькулятор-рецепты-и-себестоимость" tabindex="-1">🧮 Калькулятор: Рецепты и Себестоимость <a class="header-anchor" href="#🧮-калькулятор-рецепты-и-себестоимость" aria-label="Permalink to &quot;🧮 Калькулятор: Рецепты и Себестоимость&quot;">​</a></h1><p>Вкладка <strong>«Калькулятор»</strong> — это главный интеллектуальный центр программы. Здесь вы создаете шаблоны (технологические карты) ваших изделий и рассчитываете их точную себестоимость.</p><p>Экран разделен на два режима (переключатель сверху):</p><ol><li><strong>Расчет тиража</strong> — быстрый расчет себестоимости партии и запуск её в производство.</li><li><strong>База рецептов</strong> — управление вашим каталогом шаблонов.</li></ol><hr><h2 id="📝-создание-нового-рецепта" tabindex="-1">📝 Создание нового рецепта <a class="header-anchor" href="#📝-создание-нового-рецепта" aria-label="Permalink to &quot;📝 Создание нового рецепта&quot;">​</a></h2><p>Перейдите в режим <strong>«База рецептов»</strong> и нажмите <strong>«Создать рецепт»</strong>. Откроется конструктор.</p><h3 id="_1-основные-параметры-изделия" tabindex="-1">1. Основные параметры изделия <a class="header-anchor" href="#_1-основные-параметры-изделия" aria-label="Permalink to &quot;1. Основные параметры изделия&quot;">​</a></h3><ul><li><strong>Название:</strong> Например, <em>«Кошелек Бифолд (Черный)»</em>.</li><li><strong>Время работы (ч):</strong> Укажите, сколько часов вашего чистого времени уходит на создание одной единицы. Эта цифра будет умножена на <em>Системную ставку мастера</em> (из Настроек), чтобы включить стоимость вашего труда в себестоимость.</li></ul><h3 id="_2-накладные-расходы-коэффициенты" tabindex="-1">2. Накладные расходы (Коэффициенты) <a class="header-anchor" href="#_2-накладные-расходы-коэффициенты" aria-label="Permalink to &quot;2. Накладные расходы (Коэффициенты)&quot;">​</a></h3><p>ОмниКрафт ЕРП позволяет гибко управлять невидимыми издержками через кнопку <strong>«Настройка ставки, наценки и накладных расходов»</strong>. Программа подтягивает глобальные нормативы из Настроек пространства (например, износ станков, аренду, электричество). Вы можете применить <strong>коэффициент</strong> к конкретному изделию:</p><ul><li>Если вы шьете сложное изделие, где тратится много клея и электричества, поставьте коэффициент накладных <code>1.5</code>.</li><li>Если это простая вещь ручным швом без использования оборудования, поставьте износу оборудования коэффициент <code>0</code>, и он не добавится к цене этого товара.</li></ul><h3 id="_3-двухуровневыи-состав-сырье-и-упаковка" tabindex="-1">3. Двухуровневый состав (Сырье и Упаковка) <a class="header-anchor" href="#_3-двухуровневыи-состав-сырье-и-упаковка" aria-label="Permalink to &quot;3. Двухуровневый состав (Сырье и Упаковка)&quot;">​</a></h3><p>Рецепт в программе разделен на две вкладки:</p><ul><li><strong>Сырье изделия:</strong> Здесь вы добавляете кожу, нитки, краску. Эти материалы всегда списываются при производстве изделия на Верстаке.</li><li><strong>Сборка упаковки:</strong> Вы можете заранее собрать комплекты упаковки (например, «Стандартная» — коробка + бумага, или «Премиальная» — деревянный бокс + сургучная печать). Упаковка <strong>не списывается</strong> при производстве! Она лежит на складе до тех пор, пока вы не продадите товар и не выберете, в какую коробку его положить.</li></ul><blockquote><p>Выберите категорию, материал из наличия на складе, укажите расход на 1 штуку (например, <code>12.5</code> дм²) и нажмите кнопку <strong>«+»</strong> (Добавить).</p></blockquote><hr><h2 id="🧮-расчет-тиража-и-запуск-на-верстак" tabindex="-1">🧮 Расчет тиража и Запуск на Верстак <a class="header-anchor" href="#🧮-расчет-тиража-и-запуск-на-верстак" aria-label="Permalink to &quot;🧮 Расчет тиража и Запуск на Верстак&quot;">​</a></h2><p>Когда рецепты созданы, перейдите в режим <strong>«Расчет тиража»</strong>.</p><ol><li>Нажмите на строку поиска и выберите нужное изделие из вашей базы.</li><li>Укажите <strong>Тираж</strong> (сколько штук вы планируете сшить).</li><li>Выберите <strong>Упаковку</strong> (необязательно) — это позволит увидеть полную стоимость товара уже в подарочном виде.</li></ol><h3 id="блок-детализации-затрат" tabindex="-1">Блок Детализации затрат <a class="header-anchor" href="#блок-детализации-затрат" aria-label="Permalink to &quot;Блок Детализации затрат&quot;">​</a></h3><p>Программа мгновенно рассчитает:</p><ul><li><strong>Стоимость сырья:</strong> Берется актуальная средневзвешенная цена со склада на текущую секунду.</li><li><strong>Стоимость работы:</strong> Ваше время умножается на ставку.</li><li><strong>Накладные расходы:</strong> Включают амортизацию и фиксированные траты.</li><li><strong>Комплектация упаковки.</strong></li></ul><h3 id="запуск-в-производство" tabindex="-1">Запуск в производство <a class="header-anchor" href="#запуск-в-производство" aria-label="Permalink to &quot;Запуск в производство&quot;">​</a></h3><p>Убедившись, что цифры вас устраивают, нажмите зеленую кнопку <strong>«Запланировать производство»</strong>.</p><p><em>Программа проверит склад:</em></p><ul><li>Если материалов хватает, партия мгновенно отправится на вкладку <strong>«Производство»</strong> (на Верстак).</li><li>Если материалов не хватает, программа покажет <strong>Список дефицита</strong> (чего именно и сколько не хватает). Вы можете отменить действие или отправить партию на верстак принудительно (она будет висеть там в статусе ожидания закупки).</li></ul><hr><h2 id="🗄️-управление-базои-рецептов" tabindex="-1">🗄️ Управление базой рецептов <a class="header-anchor" href="#🗄️-управление-базои-рецептов" aria-label="Permalink to &quot;🗄️ Управление базой рецептов&quot;">​</a></h2><p>В режиме «База рецептов» вы видите удобную таблицу со всеми изделиями, где сразу показано Время изготовления, % Накладных и итоговая Себестоимость.</p><ul><li><strong>Редактирование (✏️):</strong> Вы можете в любой момент изменить рецепт (добавить нитки, изменить норму расхода кожи). <em>Примечание: изменение рецепта не затронет уже произведенные товары, лежащие на Витрине, но применится ко всем новым расчетам и заказам на Верстаке.</em></li><li><strong>Архивация (📦):</strong> Если вы сняли модель с продажи, отправьте её в архив.</li></ul><div class="warning custom-block"><p class="custom-block-title">Блокировка архивации</p><p>Программа не позволит отправить рецепт в архив, если прямо сейчас на Верстаке шьется партия этого изделия. Сначала нужно завершить или отменить пошив.</p></div>',33)])])}const h=t(s,[["render",e]]);export{u as __pageData,h as default};
